CREATE OR REPLACE PROCEDURE sp(
    para_Start_year integer,
    para_Club_name text,
    para_Club_ID integer,
    para_Player_ID integer,
    para_Occupation text,
    para_Votes integer
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_max_club_id_plus_one integer;
BEGIN
    SELECT COALESCE(MAX(Club_ID), 0) + 1
      INTO v_max_club_id_plus_one
      FROM club;

    DELETE FROM club
    WHERE Club_ID <= para_Club_ID + v_max_club_id_plus_one;

    UPDATE club
    SET Club_name = 'phase_9',
        Region = CASE
                    WHEN Start_year < para_Start_year THEN para_Club_name
                    ELSE Region
                 END;

    DELETE FROM player
    WHERE Votes < para_Votes;

    IF EXISTS (SELECT 1 FROM player WHERE Player_ID = para_Player_ID) THEN
        UPDATE player
        SET Occupation = 'log_phase_9';

        UPDATE player
        SET Sponsor_name = para_Occupation
        WHERE Player_ID = para_Player_ID;
    ELSE
        UPDATE player
        SET Sponsor_name = para_Club_name,
            Occupation = 'log_phase_9';
    END IF;
END;
$$;

